<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{auth,command,watchRoom}from'../firebase';const id=String(useRoute().params.id),room=ref<any>(),error=ref(''),online=ref(navigator.onLine);addEventListener('online',()=>online.value=true);addEventListener('offline',()=>online.value=false);onMounted(async()=>{try{await watchRoom(id,v=>room.value=v)}catch(e:any){error.value=e.message}});const me=computed(()=>room.value?.members?.[auth?.currentUser?.uid||'']);async function send(type:string,data={}){try{error.value='';await command('roomCommand',{roomId:id,type,expectedVersion:room.value.version,...data})}catch(e:any){error.value=e.message}}function copy(){navigator.clipboard.writeText(`${location.origin}${import.meta.env.BASE_URL}invite/${room.value.code}`)}</script>
<template><div v-if="!room" class="loading">{{error||'Verbindung zum Tisch wird hergestellt …'}}</div><section v-else class="room"><div v-if="!online" class="connection">Verbindung wird wiederhergestellt – Aktionen sind pausiert</div><div class="room-head"><div><small>PRIVATER TISCH</small><h1>{{room.name||'Freundschaftsrunde'}}</h1></div><button class="code" @click="copy"><small>RAUMCODE</small><b>{{room.code}}</b><span>Link kopieren</span></button></div><div v-if="room.status==='lobby'" class="lobby"><div class="panel"><h2>Sitzplatz wählen</h2><p>Tippe auf einen freien Platz. Änderungen setzen „Bereit“ zurück.</p><div class="seats"><button v-for="seat in 9" :key="seat" :class="['seat',Object.values(room.members).find((m:any)=>m.seat===seat-1)&&'taken']" @click="send('takeSeat',{seat:seat-1})"><b>{{seat}}</b><span>{{(Object.values(room.members).find((m:any)=>m.seat===seat-1) as any)?.name||'Frei'}}</span></button></div></div><aside class="panel settings"><h2>Spiel bereitmachen</h2><label>Startstack<input :value="room.settings.stack" type="number" :disabled="!me?.host" @change="send('settings',{stack:+($event.target as HTMLInputElement).value})"></label><div class="twocol"><label>Small Blind<input :value="room.settings.sb" disabled></label><label>Big Blind<input :value="room.settings.bb" disabled></label></div><button @click="send('ready')" :class="me?.ready?'ready':''">{{me?.ready?'✓ Bereit':'Ich bin bereit'}}</button><button v-if="me?.host" class="primary" @click="send('start')">Pokerabend starten</button></aside></div><div v-else class="table-wrap"><div class="table"><div class="felt"><div><small>{{room.game.phase}}</small><div class="pot-chip">{{room.game.pot||0}}</div><strong>IM POT</strong></div></div><div v-for="p in room.game.players" :key="p.uid" class="player" :style="{gridArea:`s${p.seat}`}" :class="{turn:room.game.turn===p.uid,folded:p.folded}"><span class="avatar">{{p.name[0]}}</span><b>{{p.name}}</b><span>{{p.stack.toLocaleString('de-DE')}} Chips</span><i v-if="p.roundBet">{{p.roundBet}}</i></div></div><div class="actionbar"><button @click="send('act',{move:{kind:'fold'}})">Passen</button><button @click="send('act',{move:{kind:'check'}})">Check</button><button class="primary" @click="send('act',{move:{kind:'call'}})">Mitgehen</button><button @click="send('act',{move:{kind:'all-in'}})">All-in</button></div></div><p class="error">{{error}}</p></section></template>
